import csv

# Verify RFC 4180 compliance: check for proper quoting
# RFC 4180: fields containing comma, double-quote, or newline must be quoted
# Let's check if any fields need quoting

with open('outputs/t13_city_clusters.csv', 'r', encoding='utf-8', newline='') as f:
    content = f.read()

# Check if there are any unquoted fields with commas
lines = content.split('\n')
for i, line in enumerate(lines[:20]):
    if line.strip():
        # Count commas outside quotes
        in_quote = False
        comma_count = 0
        for c in line:
            if c == '\"':
                in_quote = not in_quote
            elif c == ',' and not in_quote:
                comma_count += 1
        print(f'Line {i}: {comma_count} commas, content: {repr(line[:100])}')""}

